function dxCountry(call){
 let value=call.toUpperCase();
 if(dxCountries.exact[value])return dxCountries.exact[value];
 if(/\/(MM|AM)$/.test(value))return '—';
 value=value.replace(/\/(P|M|QRP|QRPP)$/,'');
 const parts=value.split('/');
 if(parts.length===2){const prefix=parts.find(x=>x.length<=4&&dxCountries.prefixes[x]);if(prefix)return dxCountries.prefixes[prefix];}
 for(let n=value.length;n>0;n--){if(dxCountries.prefixes[value.slice(0,n)])return dxCountries.prefixes[value.slice(0,n)];}
 return '—';
}
function locatorAt(lat,lon,length=6){
 let x=Math.max(0,Math.min(360-1e-10,lon+180)),y=Math.max(0,Math.min(180-1e-10,lat+90));
 let dx=20,dy=10,s='';
 for(let i=0;i<length;i+=2){
  const letters=i%4===0;
  if(i>0){const base=letters?24:10;dx/=base;dy/=base;}
  const ix=Math.floor((x+1e-12)/dx),iy=Math.floor((y+1e-12)/dy);
  s+=letters?String.fromCharCode(65+ix,65+iy):String(ix)+String(iy);
  x-=ix*dx;y-=iy*dy;
 }
 return s;
}
export function spotLocation(spot,contacts=[]){
 const valid=value=>{const grid=String(value||'').trim().toUpperCase();return locatorPosition(grid)?grid:'';};
 const direct=valid(spot.grid)||valid(spot.locator);
 if(direct)return {grid:direct,source:'Locator indicado no DX Cluster.'};
 const saved=contacts.find(c=>String(c.call).toUpperCase()===String(spot.call).toUpperCase()&&valid(c.locator));
 if(saved)return {grid:valid(saved.locator),source:'Locator guardado no histórico.'};
 // Two locators in a report can identify both ends; do not guess which is RX.
 const grids=String(spot.comment||'').toUpperCase().match(/\b[A-R]{2}\d{2}(?:[A-X]{2}(?:\d{2}(?:[A-X]{2})?)?)?\b/g)||[];
 if(grids.length===1&&valid(grids[0]))return {grid:grids[0],source:'Locator mencionado no spot. Confirme se corresponde ao contacto.'};
 const country=dxCountry(String(spot.call||'').trim()),center=dxCountryCenters[country];
 if(center)return {grid:locatorAt(center[0],center[1]),source:'Localização aproximada: '+country+'. Corrija o locator se o conhecer.'};
 return {grid:'',source:'Locator não disponível. Introduza o locator RX para calcular.'};
}
